// src/modules/social-chat/social-chat.routes.ts
import { FastifyPluginAsync } from 'fastify';
import { socialChatService } from './social-chat.service';
import type { SendMessageInput } from './social-chat.types';
import { sendMessageSchema } from './social-chat.schemas';

const socialChatRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * POST /social-chat/send-message
   * Envia uma mensagem e processa automaticamente (intent, categorias, ações)
   */
  fastify.post<{
    Body: {
      conversationId?: string;
      text?: string;
      audioUrl?: string;
      media?: Array<{
        type: 'image' | 'video' | 'audio';
        url: string;
        thumbnailUrl?: string;
        duration?: number;
        metadata?: Record<string, any>;
      }>;
      metadata?: Record<string, any>;
    };
  }>(
    '/send-message',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            conversationId: { type: 'string' },
            text: { type: 'string' },
            audioUrl: { type: 'string' },
            media: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  type: { type: 'string', enum: ['image', 'video', 'audio'] },
                  url: { type: 'string' },
                  thumbnailUrl: { type: 'string' },
                  duration: { type: 'number' },
                  metadata: { type: 'object' },
                },
              },
            },
            metadata: { type: 'object' },
          },
        },
      },
    },
    async (req, reply) => {
      if (!req.user) {
        return reply.status(401).send({ error: 'Não autenticado' });
      }

      if (!req.user.globalUserId) {
        return reply.status(404).send({ error: 'Identidade global não encontrada' });
      }

      if (!req.tenant) {
        return reply.status(400).send({ error: 'Tenant não encontrado' });
      }

      try {
        const validated = sendMessageSchema.parse(req.body);
        const message = await socialChatService.sendMessage(
          req.server,
          req.tenant.id,
          req.user.globalUserId,
          validated as SendMessageInput
        );
        return reply.status(201).send(message);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        fastify.log.error({ err: error }, 'Erro ao enviar mensagem');
        return reply.status(500).send({ error: 'Erro ao enviar mensagem' });
      }
    }
  );

  /**
   * GET /social-chat/conversation/:id
   * Retorna conversa completa com mensagens e ações vinculadas
   */
  fastify.get<{
    Params: { id: string };
  }>(
    '/conversation/:id',
    {
      schema: {
        params: {
          type: 'object',
          properties: {
            id: { type: 'string' },
          },
        },
      },
    },
    async (req, reply) => {
      if (!req.user) {
        return reply.status(401).send({ error: 'Não autenticado' });
      }

      if (!req.tenant) {
        return reply.status(400).send({ error: 'Tenant não encontrado' });
      }

      try {
        const conversation = await socialChatService.getConversation(
          req.tenant.id,
          req.params.id
        );
        return conversation;
      } catch (error) {
        fastify.log.error({ err: error }, 'Erro ao buscar conversa');
        return reply.status(500).send({ error: 'Erro ao buscar conversa' });
      }
    }
  );

  /**
   * GET /social-chat/message/:messageId
   * Busca uma mensagem específica
   */
  fastify.get<{
    Params: { messageId: string };
  }>(
    '/message/:messageId',
    {
      schema: {
        params: {
          type: 'object',
          properties: {
            messageId: { type: 'string' },
          },
        },
      },
    },
    async (req, reply) => {
      if (!req.user) {
        return reply.status(401).send({ error: 'Não autenticado' });
      }

      if (!req.tenant) {
        return reply.status(400).send({ error: 'Tenant não encontrado' });
      }

      try {
        const message = await socialChatService.getMessage(
          req.tenant.id,
          req.params.messageId
        );

        if (!message) {
          return reply.status(404).send({ error: 'Mensagem não encontrada' });
        }

        return message;
      } catch (error) {
        fastify.log.error({ err: error }, 'Erro ao buscar mensagem');
        return reply.status(500).send({ error: 'Erro ao buscar mensagem' });
      }
    }
  );
};

export default socialChatRoutes;












